const D = { density: .55, scale: 1, energy: .5, wind: .5, sun: .5, stones: 7, hue: 150, speed: 1, x: .32, y: .62, style: 'heath', act: 'dusk', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 150;
const lerp3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];

const STY = {
  heath:     { sky:[[205,20,30],[160,14,44],[38,30,60]], ground:[150,16,20], stone:[205,10,17], slit:[40,14,54], fog:[185,7,74], line:false, hatch:false },
  ink:       { sky:[[35,4,92],[33,6,84],[30,9,76]],      ground:[30,7,52],   stone:[220,10,15], slit:[30,6,64],  fog:[32,3,88],  line:false, hatch:true  },
  blueprint: { sky:[[214,78,13],[213,70,19],[212,62,26]],ground:[212,60,16], stone:[190,24,96], slit:[190,30,80],fog:[196,40,40], line:true,  hatch:false },
  thermal:   { sky:[[240,58,9],[232,52,15],[220,46,22]], ground:[228,44,14], stone:[22,90,94],  slit:[46,88,90], fog:[210,44,40], line:false, hatch:false },
  engraving: { sky:[[40,9,80],[38,10,70],[36,12,60]],    ground:[36,12,40],  stone:[30,10,20],  slit:[38,10,52], fog:[38,6,74],  line:false, hatch:true  } };
const st = STY[P.style] || STY.heath;
const shift = c => [hw(c[0] + ho), c[1], c[2]];

// ---- cached sky gradient + starfield ----
const key = width + 'x' + height + P.style + P.seed + Math.round(P.hue);
if (!S.sky || S.key !== key) {
  if (!S.sky) S.sky = createGraphics(width, height); else S.sky.resizeCanvas(width, height);
  const g = S.sky; g.colorMode(g.HSB, 360, 100, 100, 100); g.noStroke();
  const c = st.sky.map(shift);
  for (let yy = 0; yy < height; yy++) {
    const t = yy / height; let col;
    if (t < 0.55) col = lerp3(c[0], c[1], t / 0.55); else col = lerp3(c[1], c[2], (t - 0.55) / 0.45);
    g.fill(col[0], col[1], col[2]); g.rect(0, yy, width, 1);
  }
  // faint speckle / stars high in sky
  const ns = 46 + Math.floor(P.seed % 34);
  for (let i = 0; i < ns; i++) {
    const sx = fr(i*4+1) * width, sy = fr(i*4+2) * height * 0.42;
    g.fill(hw(st.slit[0] + ho), 8, st.line ? 90 : 84, 26 * fr(i*4+3));
    g.rect(sx, sy, 1.3, 1.3);
  }
  S.key = key;
}
image(S.sky, 0, 0);

// ---- act / section slow drift (day <-> dusk) ----
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const arc = [.2,.35,.55,.75,.4,.6,.85,.5][sec];
const ACT = { dusk:{ dk:.10+arc*.30, warm:1 }, dawn:{ dk:.34-arc*.28, warm:.7 }, storm:{ dk:.18+arc*.22, warm:.3 } };
const act = ACT[P.act] || ACT.dusk;
const dusk = act.dk + 0.05 * Math.sin(K.t * 0.018);
push(); noStroke(); fill(hw(232 + ho), 30, 8, 46 * dusk); rect(0, 0, width, height); pop();

const horY = height * P.y;

// ---- distant ridge silhouettes (parallax) ----
for (let L = 0; L < 2; L++) {
  const gy = horY - u * (0.02 + L * 0.03);
  const amp = u * (0.03 + L * 0.02);
  const dx = Math.sin(K.t * 0.01 * (1 + L)) * u * 0.01;
  const col = shift(st.ground); const v = col[2] * (0.7 + L * 0.18);
  noStroke(); fill(col[0], col[1] * 0.8, v, 90);
  beginShape(); vertex(-10, height + 10); vertex(-10, gy);
  for (let sxp = 0; sxp <= width + 40; sxp += 40) {
    const n = Math.sin(sxp * 0.006 + L * 3 + fr(L*7) * 6) + 0.5 * Math.sin(sxp * 0.017 + L);
    vertex(sxp + dx, gy - n * amp);
  }
  vertex(width + 10, height + 10); endShape(CLOSE);
}

// ---- heath ground with tonal wash bands ----
const gcol = shift(st.ground);
noStroke(); fill(gcol[0], gcol[1], gcol[2]); rect(0, horY, width, height - horY);
for (let bnd = 0; bnd < 3; bnd++) {
  const by = horY + (height - horY) * (0.2 + bnd * 0.28);
  fill(gcol[0], gcol[1], gcol[2] * (0.7 - bnd * 0.08), 30);
  rect(0, by, width, (height - horY) * 0.18);
}

// ---- low sun glow ----
const sunV = 0.25 + P.sun * 0.75;
const sx = P.x * width + Math.sin(K.t * 0.012) * u * 0.02;
const sy = horY - u * 0.015 * sunV;
push(); blendMode(ADD); noStroke();
const breathe = 0.8 + 0.35 * K.swell + 0.5 * A.rms;
const gv = (st.line ? 22 : 40) * sunV * breathe * act.warm;
for (let r = 0; r < 4; r++) {
  fill(hw(38 + ho + 6 * Math.sin(K.t * 0.02)), 60, 46, gv * (1 - r * 0.2));
  ellipse(sx, sy, u * (0.5 + r * 0.4) * (0.6 + P.sun), u * (0.3 + r * 0.22) * (0.6 + P.sun));
}
if (sunV > 0.4) { fill(hw(44 + ho), 30, 90, 30 * sunV); ellipse(sx, sy, u * 0.11 * sunV, u * 0.11 * sunV); }
blendMode(BLEND); pop();

// ---- standing stones ----
const NST = Math.max(2, Math.min(16, Math.round(P.stones)));
const lightAng = (sx / width - 0.5);
for (let i = 0; i < NST; i++) {
  const f0 = fr(i*3+1);
  const spx = width * (0.08 + f0 * 0.86);
  const depth = 0.3 + fr(i*3+2) * 0.7;               // near stones bigger/lower
  const spy = horY + (height - horY) * (0.02 + depth * 0.5);
  const h = u * (0.10 + fr(i*3+3) * 0.16) * P.scale * (0.55 + depth * 0.7);
  const w = h * (0.24 + fr(i*5+2) * 0.16);
  const lean = (fr(i*5+4) - 0.5) * 0.28;
  const sc = shift(st.stone); const vv = sc[2] * (0.5 + depth * 0.5);
  push(); translate(spx, spy); rotate(lean * 0.4);
  if (st.line) {
    stroke(sc[0], sc[1], vv, 90); strokeWeight(1.3); noFill();
    beginShape(); vertex(-w*0.5, 0); vertex(-w*0.42, -h*0.6); vertex(-w*0.28, -h);
    vertex(w*0.3, -h*0.98); vertex(w*0.46, -h*0.55); vertex(w*0.5, 0); endShape(CLOSE);
    line(0, 0, 0, -h*0.9);
  } else {
    noStroke(); fill(sc[0], sc[1], vv * 0.72);
    beginShape(); vertex(-w*0.5, 0); vertex(-w*0.44, -h*0.6); vertex(-w*0.3, -h);
    vertex(w*0.3, -h*0.98); vertex(w*0.46, -h*0.55); vertex(w*0.5, 0); endShape(CLOSE);
    // sun-lit edge
    const le = lightAng < 0 ? -1 : 1;
    fill(hw(st.slit[0] + ho), st.slit[1], st.slit[2] * (0.5 + sunV * 0.5), 60);
    beginShape(); vertex(le*w*0.5, 0); vertex(le*w*0.46, -h*0.55); vertex(le*w*0.3, -h*0.98);
    vertex(le*w*0.18, -h*0.96); vertex(le*w*0.34, -h*0.5); vertex(le*w*0.36, 0); endShape(CLOSE);
    if (st.hatch) {
      stroke(sc[0], sc[1], vv * 0.4, 40); strokeWeight(0.8);
      for (let hy = -h*0.9; hy < -h*0.05; hy += Math.max(3, h*0.08)) line(-w*0.4, hy, w*0.4, hy + w*0.3);
      noStroke();
    }
  }
  pop();
}

// ---- rolling fog banks (continuous K.t drift, wraps) ----
push(); noStroke();
const fc = shift(st.fog);
const nb = 3 + Math.round(P.density * 4);
const fA = (st.line ? 5 : 9) + P.density * 20;
for (let i = 0; i < nb; i++) {
  const fy = horY - u * 0.04 + (height - horY + u * 0.08) * (i / nb) + Math.sin(K.t * 0.05 + i) * u * 0.01;
  const spd = (0.006 + (i % 3) * 0.004) * (i % 2 ? 1 : -1) * (0.6 + P.wind * 1.6) * P.speed;
  const bw = width * (0.7 + (i % 3) * 0.25);
  const off = ((K.t * spd * width + i * 137) % (width + bw) + (width + bw)) % (width + bw) - bw;
  const bh = u * (0.10 + (i % 3) * 0.05);
  const a = fA * (0.5 + 0.5 * Math.sin(K.t * 0.03 + i * 1.7)) * (0.7 + 0.6 * (i / nb));
  for (let s = 0; s < 3; s++) {
    fill(fc[0], fc[1], fc[2], a * (0.5 - s * 0.12));
    ellipse(off + bw * 0.5, fy, bw * (1 + s * 0.2), bh * (1 + s * 0.3));
  }
}
pop();

// ---- shivering foreground grass ----
push();
const gn = Math.round((30 + P.density * 70));
const gy0 = height - u * 0.02;
const shiver = (0.6 + P.energy * 1.6);
const wind = A.lowmid * 1.2 + 0.4 * Math.sin(K.t * 0.3);
const gcolF = shift(st.ground);
for (let i = 0; i < gn; i++) {
  const gx = (i + fr(i) * 0.8) / gn * width;
  const gh = u * (0.03 + fr(i*2+1) * 0.06) * (0.8 + P.energy * 0.5);
  const sw = (Math.sin(K.t * (1.4 + fr(i)*1.2) + i * 0.7) * shiver + wind) * gh * 0.28;
  stroke(gcolF[0], gcolF[1] * 1.1, gcolF[2] * (0.5 + fr(i*3)*0.4), 85);
  strokeWeight(Math.max(1, u * 0.0016));
  noFill();
  beginShape(); vertex(gx, gy0 + u*0.02); vertex(gx + sw*0.4, gy0 - gh*0.55); vertex(gx + sw, gy0 - gh); endShape();
}
pop();
blendMode(BLEND);
